-- HotelBookingAPI - Supabase/PostgreSQL database schema
-- Run this script in Supabase Dashboard -> SQL Editor.
-- The quoted PascalCase identifiers intentionally match the current EF Core models.

begin;

create table if not exists public."RoomTypes" (
    "Id" integer generated by default as identity primary key,
    "Name" text not null,
    "Description" text,
    "PricePerNight" numeric(18, 2) not null,
    "Capacity" integer not null
);

create table if not exists public."Amenities" (
    "Id" integer generated by default as identity primary key,
    "Name" text not null
);

create table if not exists public."Customers" (
    "Id" integer generated by default as identity primary key,
    "FullName" text not null,
    "Email" text not null,
    "Phone" text
);

create table if not exists public."Rooms" (
    "Id" integer generated by default as identity primary key,
    "RoomNumber" text not null,
    "Status" text not null default 'Available',
    "RoomTypeId" integer not null,
    constraint "FK_Rooms_RoomTypes_RoomTypeId"
        foreign key ("RoomTypeId") references public."RoomTypes" ("Id")
        on delete cascade
);

create table if not exists public."Bookings" (
    "Id" integer generated by default as identity primary key,
    "CustomerId" integer not null,
    "RoomId" integer not null,
    "CheckInDate" timestamp without time zone not null,
    "CheckOutDate" timestamp without time zone not null,
    "TotalPrice" numeric(18, 2) not null,
    "Status" text not null default 'Pending',
    constraint "FK_Bookings_Customers_CustomerId"
        foreign key ("CustomerId") references public."Customers" ("Id")
        on delete cascade,
    constraint "FK_Bookings_Rooms_RoomId"
        foreign key ("RoomId") references public."Rooms" ("Id")
        on delete cascade
);

create table if not exists public."Users" (
    "Id" integer generated by default as identity primary key,
    "Username" text not null,
    "PasswordHash" text not null,
    "Role" text not null default 'Customer',
    "CustomerId" integer,
    constraint "FK_Users_Customers_CustomerId"
        foreign key ("CustomerId") references public."Customers" ("Id")
        on delete no action
);

create table if not exists public."AmenityRoom" (
    "AmenitiesId" integer not null,
    "RoomsId" integer not null,
    primary key ("AmenitiesId", "RoomsId"),
    constraint "FK_AmenityRoom_Amenities_AmenitiesId"
        foreign key ("AmenitiesId") references public."Amenities" ("Id")
        on delete cascade,
    constraint "FK_AmenityRoom_Rooms_RoomsId"
        foreign key ("RoomsId") references public."Rooms" ("Id")
        on delete cascade
);

create unique index if not exists "IX_Customers_Email"
    on public."Customers" ("Email");

create unique index if not exists "IX_Rooms_RoomNumber"
    on public."Rooms" ("RoomNumber");

create unique index if not exists "IX_Users_Username"
    on public."Users" ("Username");

create index if not exists "IX_Rooms_RoomTypeId"
    on public."Rooms" ("RoomTypeId");

create index if not exists "IX_Bookings_CustomerId"
    on public."Bookings" ("CustomerId");

create index if not exists "IX_Bookings_RoomId"
    on public."Bookings" ("RoomId");

create index if not exists "IX_AmenityRoom_RoomsId"
    on public."AmenityRoom" ("RoomsId");

-- Seed data from HotelDbContext.OnModelCreating.
insert into public."RoomTypes" ("Id", "Name", "Description", "PricePerNight", "Capacity")
values
    (1, 'Standard', 'Phòng tiêu chuẩn', 500000, 2),
    (2, 'Deluxe', 'Phòng cao cấp', 900000, 3),
    (3, 'Suite', 'Phòng suite', 1500000, 4)
on conflict ("Id") do nothing;

insert into public."Amenities" ("Id", "Name")
values
    (1, 'WiFi'),
    (2, 'Máy lạnh'),
    (3, 'TV'),
    (4, 'Bồn tắm')
on conflict ("Id") do nothing;

insert into public."Rooms" ("Id", "RoomNumber", "Status", "RoomTypeId")
values
    (1, '101', 'Available', 1),
    (2, '201', 'Available', 2),
    (3, '301', 'Available', 3)
on conflict ("Id") do nothing;

insert into public."Customers" ("Id", "FullName", "Email", "Phone")
values
    (1, 'Nguyen Van A', 'a@gmail.com', '0900000001'),
    (2, 'Tran Thi B', 'b@gmail.com', '0900000002')
on conflict ("Id") do nothing;

insert into public."AmenityRoom" ("AmenitiesId", "RoomsId")
values
    (1, 1), (2, 1),
    (1, 2), (2, 2), (3, 2),
    (1, 3), (2, 3), (3, 3), (4, 3)
on conflict do nothing;

-- Keep identity sequences above the explicit seed IDs.
select setval(pg_get_serial_sequence('public."RoomTypes"', 'Id'),
              coalesce((select max("Id") from public."RoomTypes"), 0) + 1, false);
select setval(pg_get_serial_sequence('public."Amenities"', 'Id'),
              coalesce((select max("Id") from public."Amenities"), 0) + 1, false);
select setval(pg_get_serial_sequence('public."Rooms"', 'Id'),
              coalesce((select max("Id") from public."Rooms"), 0) + 1, false);
select setval(pg_get_serial_sequence('public."Customers"', 'Id'),
              coalesce((select max("Id") from public."Customers"), 0) + 1, false);
select setval(pg_get_serial_sequence('public."Bookings"', 'Id'),
              coalesce((select max("Id") from public."Bookings"), 0) + 1, false);
select setval(pg_get_serial_sequence('public."Users"', 'Id'),
              coalesce((select max("Id") from public."Users"), 0) + 1, false);

commit;

-- Note: the API currently creates the admin user at startup using BCrypt.
-- Do not insert a plain-text password into public."Users".
